-- Автоматично згенеровано з офіційного каталогу Papa Carlo Plato.
-- 40 моделей, кожна з офіційним головним фото.

begin;

create table if not exists public.catalog_import_backups (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  scope text not null,
  payload jsonb not null
);

select 'Papa Carlo / Plato', jsonb_build_object(
  'products', coalesce((select jsonb_agg(to_jsonb(p)) from public.products p where p.brand = 'Papa Carlo' and p.collection = 'Plato'), '[]'::jsonb),
  'specs', coalesce((select jsonb_agg(to_jsonb(s)) from public.product_specs s join public.products p on p.slug = s.product_slug where p.brand = 'Papa Carlo' and p.collection = 'Plato'), '[]'::jsonb),
  'options', coalesce((select jsonb_agg(to_jsonb(o)) from public.product_options o join public.products p on p.slug = o.product_slug where p.brand = 'Papa Carlo' and p.collection = 'Plato'), '[]'::jsonb),
  'variants', coalesce((select jsonb_agg(to_jsonb(v)) from public.product_variants v join public.products p on p.slug = v.product_slug where p.brand = 'Papa Carlo' and p.collection = 'Plato'), '[]'::jsonb),
  'media', coalesce((select jsonb_agg(to_jsonb(m)) from public.product_media m join public.products p on p.slug = m.product_slug where p.brand = 'Papa Carlo' and p.collection = 'Plato'), '[]'::jsonb),
  'sources', coalesce((select jsonb_agg(to_jsonb(src)) from public.product_sources src join public.products p on p.slug = src.product_slug where p.brand = 'Papa Carlo' and p.collection = 'Plato'), '[]'::jsonb)
);

-- Дочірні записи прибираються зовнішніми ключами каскадно; файли у Storage не видаляються.
delete from public.products where brand = 'Papa Carlo' and collection = 'Plato';

on conflict (slug) do update set
  name = excluded.name, material = excluded.material, style = excluded.style, color = excluded.color,
  description = excluded.description, features = excluded.features, image_path = excluded.image_path,
  sort_order = excluded.sort_order, is_available = true, updated_at = now();

on conflict (product_slug, label) do update set value = excluded.value, sort_order = excluded.sort_order, is_active = true;

on conflict (product_slug, kind, image_path) do update set label = excluded.label, sort_order = excluded.sort_order, is_active = true;

on conflict (product_slug, source_url) do update set source_product_name = excluded.source_product_name, verification_status = 'verified', verified_at = now(), notes = excluded.notes;

commit;

select count(*) as моделей_у_plato, count(*) filter (where is_available) as опубліковано
from public.products
where brand = 'Papa Carlo' and collection = 'Plato';
